import { LitElement, html, TemplateResult, PropertyValues } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import '@awesome.me/webawesome/dist/components/input/input.js';

export class Option {
  value: string;
  description: string;
  constructor(value: string, description: string) {
    this.value = value;
    this.description = description;
  }
}

type OnSearchFn =
  | ((q: string) => Option[] | string[] | Promise<Option[] | string[]>)
  | undefined;

@customElement('lexml-autocomplete-universal')
export class LexmlAutocompleteUniversal extends LitElement {
  // ---------- UI props ----------
  @property({ type: String }) label = '';
  @property({ type: String }) placeholder = '';
  @property({ type: Boolean, reflect: true }) disabled = false;
  @property({ type: Boolean, reflect: true }) readonly = false;
  @property({ type: Boolean }) showOnEmpty = false;

  // ---------- Modo de operação ----------
  // Preferir 'mode'; manter 'async' como alias p/ retrocompatibilidade.
  @property({ type: String }) mode: 'sync' | 'async' = 'sync';
  @property({ type: Boolean, reflect: true })
  set async(v: boolean) {
    this.mode = v ? 'async' : 'sync';
  }
  get async() {
    return this.mode === 'async';
  }

  // ---------- Dados / callbacks ----------
  // Para 'sync': pode ser string[] ou Option[]
  @property({ type: Array }) items: Array<string | Option> = [];

  // Para 'async': callback de busca
  @property({ attribute: false }) onSearch: OnSearchFn = undefined;

  @property({ attribute: false }) onSelect: (opt: Option) => void = () => {};
  @property({ attribute: false }) onChange: (value: string) => void = () => {};
  @property({ attribute: false }) onClick: (value: string) => void = () => {};

  // ---------- Comportamento ----------
  @property({ type: Number }) minChars = 3;
  @property({ type: Number }) maxSuggestions = 10;
  @property({ type: Boolean, reflect: true }) opened = false;

  // ---------- Internos ----------
  private _inputEl: any;
  private _suggestionEl: any;
  private _highlightedEl: any;
  private _bound: any = {};
  private _timer: any;
  private _interval = 300; // debounce
  private _blur = false;

  // Valor sempre string no input
  private _tempValue?: string;
  get value(): string {
    return (this.contentElement && this.contentElement.value) || '';
  }
  @property({ type: String })
  set value(v: string) {
    if (!this.contentElement) {
      this._tempValue = v;
      return;
    }
    this.contentElement.value = v ?? '';
  }

  // Render
  render(): TemplateResult {
    return html`
      <style>
        .suggest-container {
          position: relative;
        }
        ul {
          position: absolute;
          display: block;
          list-style-type: none;
          margin: 0;
          padding: 0;
          z-index: 10000;
          border: 1px solid #ccc;
          background: #fff;
          overflow: auto;
        }
        li {
          padding: 6px 8px;
          cursor: pointer;
        }
        li.active {
          background: #f5f5f5;
        }
        [hidden] {
          display: none;
        }
        .lexml-autocomplete-input {
          width: 100%;
        }
        wa-input {
          font-size: 14px;
        }
      </style>

      <slot id="dropdown-input">
        <wa-input
          id="defaultInput"
          class="lexml-autocomplete-input"
          type="text"
          .value=${this.value || ''}
          label=${this.label}
          placeholder=${this.placeholder}
          ?disabled=${this.disabled}
          ?readonly=${this.readonly}
        ></wa-input>
      </slot>

      <div class="suggest-container">
        <ul
          id="suggestions"
          ?hidden=${!this.opened}
          @mousedown=${(e: MouseEvent): void => e.preventDefault()}
        >
          ${this._currentOptions.map(
            (opt: Option) =>
              html` <li
                @click=${(): void => this._selectOption(opt)}
                title=${opt.description}
              >
                ${opt.description}
              </li>`,
          )}
        </ul>
      </div>
    `;
  }

  // ---------------- lifecycle / element refs ----------------
  get contentElement(): any {
    if (this._inputEl) return this._inputEl;
    if (!this.hasUpdated) return undefined;
    const slotEl = this.shadowRoot!.getElementById(
      'dropdown-input',
    ) as HTMLSlotElement;
    const assigned = slotEl.assignedElements();
    this._inputEl = assigned.length
      ? assigned[0]
      : this.shadowRoot!.getElementById('defaultInput');
    return this._inputEl;
  }

  private _syncListWidth = () => {
    if (!this._suggestionEl || !this.contentElement) return;
    const w = this.contentElement.getBoundingClientRect().width || 0;
    if (w > 0) {
      this._suggestionEl.style.boxSizing = 'border-box';
      this._suggestionEl.style.minWidth = `${w}px`;
      this._suggestionEl.style.width = `${w}px`;
    }
  };

  private _ro?: ResizeObserver;
  private _io?: IntersectionObserver;

  firstUpdated(): void {
    this._suggestionEl = this.shadowRoot!.getElementById('suggestions');

    this._syncListWidth();
    this._ro = new ResizeObserver(() => this._syncListWidth());
    this._ro.observe(this.contentElement);
    this._io = new IntersectionObserver(
      entries => {
        if (entries[0].isIntersecting) this._syncListWidth();
      },
      { threshold: 0.01 },
    );
    this._io.observe(this);
    this._bound.onKeyDown = this._handleKeyDown.bind(this);
    this._bound.onKeyUp = this._handleKeyUp.bind(this);
    this._bound.onFocus = this._handleFocus.bind(this);
    this._bound.onBlur = this._handleBlur.bind(this);
    this._bound.onChange = (e: any): void =>
      this._handleChange(e?.target?.value ?? this.value);
    this._bound.onClick = (e: any): void =>
      this._handleClick(e?.target?.value ?? this.value);

    const el = this.contentElement;
    el.addEventListener('keydown', this._bound.onKeyDown);
    el.addEventListener('keyup', this._bound.onKeyUp);
    el.addEventListener('focus', this._bound.onFocus);
    el.addEventListener('blur', this._bound.onBlur);
    el.addEventListener('wa-input', this._bound.onChange);
    el.addEventListener('click', this._bound.onClick);

    if (this._tempValue !== undefined) el.value = this._tempValue;
    this._recalcList(); // primeira passada
  }

  disconnectedCallback(): void {
    this._ro?.disconnect();
    this._io?.disconnect();
    window.removeEventListener('resize', this._syncListWidth);
    if (this.contentElement) {
      const el = this.contentElement;
      el.removeEventListener('keydown', this._bound.onKeyDown);
      el.removeEventListener('keyup', this._bound.onKeyUp);
      el.removeEventListener('focus', this._bound.onFocus);
      el.removeEventListener('blur', this._bound.onBlur);
      el.removeEventListener('wa-input', this._bound.onChange);
      el.removeEventListener('click', this._bound.onClick);
    }
    super.disconnectedCallback();
  }

  updated(changed: PropertyValues): void {
    if (changed.has('items') || changed.has('mode')) {
      this._recalcList();
    }
    if (
      changed.has('opened') &&
      this.opened &&
      this._suggestionEl?.childElementCount
    ) {
      this._highlightedEl = this._suggestionEl.children[0];
      this._highlightedEl.classList.add('active');
    }
  }

  // ---------------- suggestions state ----------------
  private _currentOptions: Option[] = [];

  private _itemsToOptions(src: Array<string | Option>): Option[] {
    return (src || []).map(it =>
      typeof it === 'string' ? new Option(it, it) : it,
    );
  }

  private _recalcList(): void {
    if (this.mode === 'sync') {
      this._currentOptions = this.showOnEmpty
        ? this._itemsToOptions(this.items).slice(0, this.maxSuggestions)
        : [];
      this.requestUpdate();
    }
  }

  private _setSuggestions(list: Array<string | Option>): void {
    this._currentOptions = this._itemsToOptions(list).slice(
      0,
      this.maxSuggestions,
    );
    this._currentOptions.length ? this.open() : this.close();
    this.requestUpdate();
  }

  // ---------------- open/close ----------------
  open(): void {
    this._syncListWidth();
    if (this._currentOptions.length) this.opened = true;
  }
  close(): void {
    this.opened = false;
    this._highlightedEl = null;
  }

  // ---------------- select ----------------
  private _selectOption(opt: Option) {
    // escreve só o texto no input (sempre string)
    this.contentElement.value = opt?.description ?? '';
    this.onSelect?.(opt);

    // compat com o autocomplete "antigo" que emitia evento
    this.dispatchEvent(
      new CustomEvent('autocomplete', {
        bubbles: true,
        composed: true,
        detail: { value: this.contentElement.value, option: opt },
      }),
    );

    this.close();
    this.contentElement?.focus?.();
  }

  // ---------------- keyboard / input handlers ----------------
  private _handleKeyDown(ev: KeyboardEvent): void {
    if (ev.key === 'ArrowUp' || ev.key === 'ArrowDown') {
      ev.preventDefault();
      ev.stopPropagation();
    }
  }

  private _handleKeyUp(ev: KeyboardEvent): void {
    switch (ev.key) {
      case 'ArrowUp':
        if (this._highlightedEl?.previousElementSibling) {
          ev.preventDefault();
          ev.stopPropagation();
          this._highlightedEl.classList.remove('active');
          this._highlightedEl = this._highlightedEl.previousElementSibling;
          this._highlightedEl.classList.add('active');
        }
        break;
      case 'ArrowDown':
        if (this._highlightedEl?.nextElementSibling) {
          ev.preventDefault();
          ev.stopPropagation();
          this._highlightedEl.classList.remove('active');
          this._highlightedEl = this._highlightedEl.nextElementSibling;
          this._highlightedEl.classList.add('active');
        } else if (!this.opened && this._currentOptions.length) {
          this.open();
        }
        break;
      case 'Enter':
        (this._highlightedEl as HTMLElement)?.click?.();
        this.contentElement.blur();
        break;
      default:
        this._debouncedSearch();
    }
  }

  private _debouncedSearch() {
    const q: string = this.value || '';
    clearTimeout(this._timer);

    const run = async () => {
      if (this.mode === 'async') {
        if (!this.onSearch) return;
        if ((q?.length ?? 0) < this.minChars) {
          this._setSuggestions([]);
          return;
        }

        try {
          const res = await this.onSearch(q);
          this._setSuggestions(Array.isArray(res) ? res : []);
        } catch {
          this._setSuggestions([]);
        }
      } else {
        // sync local: filtra items se fornecidos
        const base = this._itemsToOptions(this.items);
        if (!q) {
          this._setSuggestions([]);
          return;
        }
        const norm = (s: string): string =>
          s
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .toLowerCase();
        const nq = norm(q);

        // começa com, depois contém
        let out = base
          .filter(o => norm(o.description).startsWith(nq))
          .slice(0, this.maxSuggestions);
        if (out.length < this.maxSuggestions) {
          out = [
            ...out,
            ...base.filter(
              o =>
                norm(o.description).includes(nq) &&
                !out.some(x => x.value === o.value),
            ),
          ].slice(0, this.maxSuggestions);
        }
        this._setSuggestions(out);
      }
    };

    this._timer = setTimeout(run, this._interval);
  }

  private _handleFocus(): void {
    this._blur = false;
    if (this._currentOptions.length > 1) this.open();
  }

  private _handleBlur(): void {
    this._blur = true;
    setTimeout(() => this.close(), 200);
  }

  private _handleChange(value: string): void {
    this.onChange?.(value);
  }
  private _handleClick(value: string): void {
    this.onClick?.(value);
    if (this.mode === 'sync') {
      const q = (this.value ?? '').trim();
      if (!q) {
        if (this.showOnEmpty) this._setSuggestions(this.items as any);
        else this.close();
        return;
      }
      if (this._currentOptions.length) this.open();
    }
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'lexml-autocomplete-universal': LexmlAutocompleteUniversal;
  }
}
